export default async function run(ctx) {
  await ctx.page.goto("__FX_URL__/fake-gram");

  const guards = [
    ctx.guard.url("fake-gram"),
    ctx.guard.exists("#create-post", { timeout: 8000 }),
    ctx.guard.noDialog(),
  ];
  if (!(await ctx.guard.all(guards))) {
    return ctx.deopt(
      "Compose the queued caption on FakeGram, submit the create-post form and emit post.published with the caption.",
      { failed: await ctx.guard.failures() },
    );
  }

  await ctx.page.type("#create-post input[name='caption']", "a caption");
  await ctx.page.click("#create-post button[type='submit']");

  const posted = await ctx.page.evalExtract("#create-post", {
    caption: { selector: "input[name='caption']", attr: "value" },
  });
  for (const row of posted) {
    await ctx.emitIfNew("post.published", row, { dedupeKey: row.caption });
  }
}
